ALPHA = "אבגדהוזחטיכלמנסעפצקרשת"
FINALS = {"ך": "כ", "ם": "מ", "ן": "נ", "ף": "פ", "ץ": "צ"}
def atbash(word):
    out = ""
    for ch in word:
        if ch in FINALS:
            ch = FINALS[ch]
        i = ALPHA.find(ch)
        if i >= 0:
            out = out + ALPHA[21 - i]
        else:
            out = out + ch
    return out

def notarikon(words):
    out = ""
    for w in words:
        out = out + w[0].upper()
    return out

